    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather (precipitation, snow, or extreme cold) on 2024-11-28 reduced trip demand relative to baseline Thursdays.",
      "support_if": "nyc_weather_daily shows significant prcp_mm, snow_mm, or low tmax_c on 2024-11-28 vs. baseline Thursdays.",
      "refute_if": "Weather on 2024-11-28 is similar to or better than baseline Thursdays."
    },
    {
      "id": "H3",
      "kind": "fare_mix",
      "statement": "The mix of trip distances or fares shifted on 2024-11-28 (e.g., fewer short trips, more long trips), indicating a demand composition change rather than pure volume drop.",
