      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Check if 2024-11-28 and baseline Thursdays are holidays in whybot.us_holidays; return holiday_name and is_national for each date.",
      "tables": ["whybot.us_holidays"]
