      "hypothesis_id": "H2",
      "purpose": "Get prcp_mm, snow_mm, tmax_c, tmin_c for 2024-11-28 and baseline Thursdays from whybot.nyc_weather_daily.",
      "tables": ["whybot.nyc_weather_daily"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compare avg_trip_distance and avg_total_amount on 2024-11-28 vs. baseline Thursdays from whybot.yellow_daily (same rows as H0).",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Verify data existence for 2024-11-28 and baseline Thursdays in whybot.yellow_daily; check TPCDS_DB.date_dim d_holiday flag for disagreement with us_holidays.",
